codingPractice.solution:
def soma_pares(n):
    total = 0
    for i in range(n + 1):
        if i % 2 == 0:
            total += i
    return total
assert soma_pares(0) == 0
assert soma_pares(5) == 6
assert soma_pares(6) == 12
